    gv_output.mode = GV_FAULT;
    return;
}
if ((!isfinite(gv_config.threshold_rad_s)) || (gv_config.threshold_rad_s < 0.0) ||
    (!isfinite(gv_config.reentry_threshold_rad_s)) ||
    (gv_config.reentry_threshold_rad_s < 0.0) ||
    (gv_config.reentry_threshold_rad_s > gv_config.threshold_rad_s) ||
    (gv_config.isolate_confirm < 1U) || (gv_config.isolate_confirm > 20U) ||
    (gv_config.reentry_confirm < 1U) || (gv_config.reentry_confirm > 20U)) {
    gv_state.isolated[0] = 0; gv_state.isolated[1] = 0; gv_state.isolated[2] = 0;
