{
    const adcs_vec3_t *g0 = gv_input.gyro[0];
    const adcs_vec3_t *g1 = gv_input.gyro[1];
    const adcs_vec3_t *g2 = gv_input.gyro[2];
    adcs_vec3_t median;
    adcs_vec3_t diff;
    double a, b, c, tmp;
    unint32 outlier_count = 0U;
    unint32 iso_count = 0U;
    size_t i;

    a = g0->x; b = g1->x; c = g2->x;
    if (a > b) { tmp = a; a = b; b = tmp; }
    if (b > c) { tmp = b; b = c; c = tmp; }
    if (a > b) { tmp = a; a = b; b = tmp; }
    median.x = b;
    a = g0->y; b = g1->y; c = g2->y;
    if (a > b) { tmp = a; a = b; b = tmp; }
    if (b > c) { tmp = b; b = c; c = tmp; }
    if (a > b) { tmp = a; a = b; b = tmp; }
    median.y = b;
    a = g0->z; b = g1->z; c = g2->z;
    if (a > b) { tmp = a; a = b; b = tmp; }
    if (b > c) { tmp = b; b = c; c = tmp; }
    if (a > b) { tmp = a; a = b; b = tmp; }
    median.z = b;

    diff = adcs_vec3_sub(g0, &median);
    gv_output.distance_rad_s[0] = adcs_vec3_norm(&diff);
    diff = adcs_vec3_sub(g1, &median);
    gv_output.distance_rad_s[1] = adcs_vec3_norm(&diff);
    diff = adcs_vec3_sub(g2, &median);
    gv_output.distance_rad_s[2] = adcs_vec3_norm(&diff);

    gv_output.outlier_mask = 0U;
    for (i = 0U; i < 3U; i++) {
        if (gv_output.distance_rad_s[i] > gv_config.threshold_rad_s) {
            gv_output.outlier_mask |= (unint32)(1U << i);
            outlier_count++;
        }
    }

    if (gv_input.enable == 0) {
        gv_state.isolated[0] = 0; gv_state.isolated[1] = 0; gv_state.isolated[2] = 0;
        gv_state.bad_streak[0] = 0U; gv_state.bad_streak[1] = 0U; gv_state.bad_streak[2] = 0U;
        gv_state.good_streak[0] = 0U; gv_state.good_streak[1] = 0U; gv_state.good_streak[2] = 0U;
        gv_state.mode = GV_OFF;
        gv_output.mode = GV_OFF;
        gv_output.voted_rate_rad_s = (adcs_vec3_t){0.0, 0.0, 0.0};
        return;
    }

    for (i = 0U; i < 3U; i++) {
        int outlier = (int)((gv_output.outlier_mask >> i) & 1U);
        if (!gv_state.isolated[i]) {
            if (outlier) {
                gv_state.bad_streak[i]++;
                if (gv_state.bad_streak[i] >= gv_config.isolate_confirm) {
                    gv_state.isolated[i] = 1;
                    gv_state.bad_streak[i] = 0U;
                    gv_state.good_streak[i] = 0U;
                }
            } else {
                gv_state.bad_streak[i] = 0U;
            }
        } else {
            if (gv_output.distance_rad_s[i] <= gv_config.reentry_threshold_rad_s) {
                gv_state.good_streak[i]++;
                if (gv_state.good_streak[i] >= gv_config.reentry_confirm) {
                    gv_state.isolated[i] = 0;
                    gv_state.good_streak[i] = 0U;
                    gv_state.bad_streak[i] = 0U;
                }
            } else {
                gv_state.good_streak[i] = 0U;
            }
        }
    }

    iso_count = 0U;
    for (i = 0U; i < 3U; i++) {
        if (gv_state.isolated[i]) iso_count++;
    }

    if (iso_count == 0U) {
        if (outlier_count == 0U) {
            gv_state.mode = GV_NOMINAL;
            gv_output.mode = GV_NOMINAL;
            gv_output.voted_rate_rad_s = median;
        } else if (outlier_count == 1U) {
            adcs_vec3_t sum = (adcs_vec3_t){0.0, 0.0, 0.0};
            gv_state.mode = GV_DEGRADED;
            gv_output.mode = GV_DEGRADED;
            for (i = 0U; i < 3U; i++) {
                if (((gv_output.outlier_mask >> i) & 1U) == 0U) {
                    sum = adcs_vec3_add(&sum, gv_input.gyro[i]);
                }
            }
            gv_output.voted_rate_rad_s = adcs_vec3_scale(&sum, 0.5);
        } else {
            gv_state.mode = GV_FAULT;
            gv_output.mode = GV_FAULT;
            gv_output.voted_rate_rad_s = (adcs_vec3_t){0.0, 0.0, 0.0};
        }
    } else if (iso_count == 1U) {
        const adcs_vec3_t *p = NULL;
        const adcs_vec3_t *q = NULL;
        adcs_vec3_t d, sum;
        for (i = 0U; i < 3U; i++) {
            if (!gv_state.isolated[i]) {
                if (p == NULL) p = gv_input.gyro[i];
                else q = gv_input.gyro[i];
            }
        }
        d = adcs_vec3_sub(p, q);
        if (adcs_vec3_norm(&d) <= gv_config.threshold_rad_s) {
            sum = adcs_vec3_add(p, q);
            gv_output.voted_rate_rad_s = adcs_vec3_scale(&sum, 0.5);
            gv_state.mode = GV_DEGRADED;
            gv_output.mode = GV_DEGRADED;
        } else {
            gv_state.mode = GV_FAULT;
            gv_output.mode = GV_FAULT;
            gv_output.voted_rate_rad_s = (adcs_vec3_t){0.0, 0.0, 0.0};
        }
    } else {
        gv_state.mode = GV_FAULT;
        gv_output.mode = GV_FAULT;
        gv_output.voted_rate_rad_s = (adcs_vec3_t){0.0, 0.0, 0.0};
    }
}

