        adcs_vec3_t sum = adcs_vec3_add(gv_input.gyro[a], gv_input.gyro[b]);
        gv_output.voted_rate_rad_s = adcs_vec3_scale(&sum, 0.5);
        gv_output.mode = GV_DEGRADED;
    } else {
        gv_output.mode = GV_FAULT;
        gv_output.voted_rate_rad_s = (adcs_vec3_t){0.0, 0.0, 0.0};
    }
} else {
    gv_output.mode = GV_FAULT;
    gv_output.voted_rate_rad_s = (adcs_vec3_t){0.0, 0.0, 0.0};
}
gv_state.mode = gv_output.mode;

candidates.misra:
uint32_t i;
uint32_t iso_count = 0U;
uint32_t out_count = 0U;
double med;

/* invalid input / configuration -> latch FAULT, zero output, OFF when disabled */
if ((gv_input.enable != 0) && (gv_input.enable != 1)) {
    gv_state.mode = GV_FAULT;
    gv_output.mode = GV_FAULT;
    gv_output.voted_rate_rad_s = (adcs_vec3_t){0.0, 0.0, 0.0};
    gv_output.distance_rad_s[0] = 0.0;
    gv_output.distance_rad_s[1] = 0.0;
    gv_output.distance_rad_s[2] = 0.0;
    gv_output.outlier_mask = 0U;
    return;
}
if (gv_input.enable == 0) {
    gv_state.bad_streak[0] = gv_state.bad_streak[1] = gv_state.bad_streak[2] = 0U;
    gv_state.good_streak[0] = gv_state.good_streak[1] = gv_state.good_streak[2] = 0U;
    gv_state.isolated[0] = gv_state.isolated[1] = gv_state.isolated[2] = 0;
    gv_state.mode = GV_OFF;
    gv_output.mode = GV_OFF;
    gv_output.voted_rate_rad_s = (adcs_vec3_t){0.0, 0.0, 0.0};
    gv_output.distance_rad_s[0] = 0.0;
    gv_output.distance_rad_s[1] = 0.0;
    gv_output.distance_rad_s[2] = 0.0;
    gv_output.outlier_mask = 0U;
    return;
}
if ((gv_input.gyro[0] == NULL) || (gv_input.gyro[1] == NULL) || (gv_input.gyro[2] == NULL) ||
    (!adcs_is_finite_vec3(gv_input.gyro[0])) || (!adcs_is_finite_vec3(gv_input.gyro[1])) ||
    (!adcs_is_finite_vec3(gv_input.gyro[2])) ||
    (!isfinite(gv_config.threshold_rad_s)) || (gv_config.threshold_rad_s < 0.0) ||
    (!isfinite(gv_config.reentry_threshold_rad_s)) ||
    (gv_config.reentry_threshold_rad_s < 0.0) ||
    (gv_config.reentry_threshold_rad_s > gv_config.threshold_rad_s) ||
    (gv_config.isolate_confirm < 1U) || (gv_config.isolate_confirm > 20U) ||
    (gv_config.reentry_confirm < 1U) || (gv_config.reentry_confirm > 20U)) {
    gv_state.mode = GV_FAULT;
    gv_output.mode = GV_FAULT;
    gv_output.voted_rate_rad_s = (adcs_vec3_t){0.0, 0.0, 0.0};
    gv_output.distance_rad_s[0] = 0.0;
    gv_output.distance_rad_s[1] = 0.0;
    gv_output.distance_rad_s[2] = 0.0;
    gv_output.outlier_mask = 0U;
    return;
}

/* component-wise median of the three raw sensors */
med = gv_input.gyro[0]->x;
if (((gv_input.gyro[1]->x <= med) && (gv_input.gyro[2]->x >= med)) ||
    ((gv_input.gyro[2]->x <= med) && (gv_input.gyro[1]->x >= med)))
    gv_output.voted_rate_rad_s.x = med;
else if (((gv_input.gyro[0]->x <= gv_input.gyro[1]->x) &&
          (gv_input.gyro[2]->x >= gv_input.gyro[1]->x)) ||
         ((gv_input.gyro[2]->x <= gv_input.gyro[1]->x) &&
          (gv_input.gyro[0]->x >= gv_input.gyro[1]->x)))
    gv_output.voted_rate_rad_s.x = gv_input.gyro[1]->x;
else
    gv_output.voted_rate_rad_s.x = gv_input.gyro[2]->x;

med = gv_input.gyro[0]->y;
if (((gv_input.gyro[1]->y <= med) && (gv_input.gyro[2]->y >= med)) ||
    ((gv_input.gyro[2]->y <= med) && (gv_input.gyro[1]->y >= med)))
    gv_output.voted_rate_rad_s.y = med;
else if (((gv_input.gyro[0]->y <= gv_input.gyro[1]->y) &&
          (gv_input.gyro[2]->y >= gv_input.gyro[1]->y)) ||
         ((gv_input.gyro[2]->y <= gv_input.gyro[1]->y) &&
          (gv_input.gyro[0]->y >= gv_input.gyro[1]->y)))
    gv_output.voted_rate_rad_s.y = gv_input.gyro[1]->y;
else
    gv_output.voted_rate_rad_s.y = gv_input.gyro[2]->y;

med = gv_input.gyro[0]->z;
if (((gv_input.gyro[1]->z <= med) && (gv_input.gyro[2]->z >= med)) ||
    ((gv_input.gyro[2]->z <= med) && (gv_input.gyro[1]->z >= med)))
    gv_output.voted_rate_rad_s.z = med;
else if (((gv_input.gyro[0]->z <= gv_input.gyro[1]->z) &&
          (gv_input.gyro[2]->z >= gv_input.gyro[1]->z)) ||
         ((gv_input.gyro[2]->z <= gv_input.gyro[1]->z) &&
          (gv_input.gyro[0]->z >= gv_input.gyro[1]->z)))
    gv_output.voted_rate_rad_s.z = gv_input.gyro[1]->z;
else
    gv_output.voted_rate_rad_s.z = gv_input.gyro[2]->z;

/* Euclidean distance of each raw sensor from the median; outlier mask */
gv_output.outlier_mask = 0U;
for (i = 0U; i < 3U; i++) {
    adcs_vec3_t d;
    d = adcs_vec3_sub(gv_input.gyro[i], &gv_output.voted_rate_rad_s);
    gv_output.distance_rad_s[i] = adcs_vec3_norm(&d);
    if (gv_output.distance_rad_s[i] > gv_config.threshold_rad_s)
        gv_output.outlier_mask |= (uint32_t)(1U << i);
}

/* streak updates using this cycle's outlier flags */
for (i = 0U; i < 3U; i++) {
    if (!gv_state.isolated[i]) {
        if ((gv_output.outlier_mask & (uint32_t)(1U << i)) != 0U) {
            gv_state.bad_streak[i]++;
            if (gv_state.bad_streak[i] >= gv_config.isolate_confirm) {
                gv_state.isolated[i] = 1;
                gv_state.bad_streak[i] = 0U;
                gv_state.good_streak[i] = 0U;
            }
        } else {
            gv_state.bad_streak[i] = 0U;
        }
    } else {
        if (gv_output.distance_rad_s[i] <= gv_config.reentry_threshold_rad_s) {
            gv_state.good_streak[i]++;
            if (gv_state.good_streak[i] >= gv_config.reentry_confirm) {
                gv_state.isolated[i] = 0;
                gv_state.bad_streak[i] = 0U;
                gv_state.good_streak[i] = 0U;
            }
        } else {
            gv_state.good_streak[i] = 0U;
        }
    }
}

/* isolate count and outlier count after streak updates */
for (i = 0U; i < 3U; i++) {
    if (gv_state.isolated[i])
        iso_count++;
}
for (i = 0U; i < 3U; i++) {
    if ((gv_output.outlier_mask & (uint32_t)(1U << i)) != 0U)
        out_count++;
}

if (iso_count == 0U) {
    if (out_count == 0U) {
        gv_output.mode = GV_NOMINAL;
    } else if (out_count == 1U) {
        uint32_t a = 3U, b = 3U, k;
        adcs_vec3_t sum;
        for (k = 0U; k < 3U; k++) {
            if ((gv_output.outlier_mask & (uint32_t)(1U << k)) == 0U) {
                if (a == 3U)
                    a = k;
                else
                    b = k;
            }
        }
        sum = adcs_vec3_add(gv_input.gyro[a], gv_input.gyro[b]);
        gv_output.voted_rate_rad_s = adcs_vec3_scale(&sum, 0.5);
        gv_output.mode = GV_DEGRADED;
    } else {
        gv_output.mode = GV_FAULT;
        gv_output.voted_rate_rad_s = (adcs_vec3_t){0.0, 0.0, 0.0};
    }
} else if (iso_count == 1U) {
    uint32_t a = 3U, b = 3U, k, iso_idx = 3U;
    adcs_vec3_t diff;
    for (k = 0U; k < 3U; k++) {
        if (gv_state.isolated[k])
            iso_idx = k;
    }
    for (k = 0U; k < 3U; k++) {
        if (k != iso_idx) {
            if (a == 3U)
                a = k;
            else
                b = k;
        }
    }
    diff = adcs_vec3_sub(gv_input.gyro[a], gv_input.gyro[b]);
    if (adcs_vec3_norm(&diff) <= gv_config.threshold_rad_s) {
        adcs_vec3_t sum = adcs_vec3_add(gv_input.gyro[a], gv_input.gyro[b]);
        gv_output.voted_rate_rad_s = adcs_vec3_scale(&sum, 0.5);
        gv_output.mode = GV_DEGRADED;
    } else {
        gv_output.mode = GV_FAULT;
        gv_output.voted_rate_rad_s = (adcs_vec3_t){0.0, 0.0, 0.0};
    }
} else {
    gv_output.mode = GV_FAULT;
    gv_output.voted_rate_rad_s = (adcs_vec3_t){0.0, 0.0, 0.0};
}
gv_state.mode = gv_output.mode;
